sys_script_include.script:
var ContrastUtilBase = Class.create();
ContrastUtilBase.prototype = {
    initialize: function() {},
    fetchAdditionalInfo: function(configId, name, params) {
        return this._makeRestCallJSON(configId, name, null, params);
    },
    getAttachment: function(attachmentGr) {
        var attachment = new GlideSysAttachment();
        var size = attachmentGr.getValue("size_bytes");
        size = parseInt(size);
        var payload = "";
        if (size >= (5 * 1024 * 1024)) {
            var attachmentSysID = attachmentGr.sys_id + "";
            var stream = attachment.getContentStream(attachmentSysID);
            var reader = new GlideTextReader(stream);
            var ln = ' ';
            while ((ln = reader.readLine()) != null) {
                payload += ln;
            }
        } else {
            payload = attachment.getContent(attachmentGr);
        }
        return JSON.parse(payload);

    },

    getDetailReport: function(configId, buildId) {
        return this._makeRestCall(configId, 'Detailed report', {
            build_id: buildId
        });
    },

    getApplicationList: function(configId) {
        return this._makeRestCall(configId, 'Application list');
    },

    getScanSummaryRecord: function(configId, app_uid, buildId) {
        var params;
        if (!gs.nil(buildId)) {
            params = {
                build_id: buildId
            };
        }
        return this._makeRestCallJSON(configId, 'Scan Summary', params, {
            app_guid: app_uid
        });
    },

    getAuthorizationDetails: function() {
        var gri = new GlideRecord('sn_sec_int_impl_config');
        gri.addEncodedQuery('implementation.name=Contrast Application Vulnerability^configuration.name=authorization');
        gri.query();
        if (gri.next()) {
            return gri.value;
        } else {
            return '';
        }
    },

    getApiKeyDetails: function() {
        var gri = new GlideRecord('sn_sec_int_impl_config');
        gri.addEncodedQuery('implementation.name=Contrast Application Vulnerability^configuration.name=api_key');
        gri.query();
        if (gri.next()) {
            return gri.value;
        } else {
            return '';
        }
    },
    getApiURLDetails: function() {
        var gri = new GlideRecord('sn_sec_int_impl_config');
        gri.addEncodedQuery('implementation.name=Contrast Application Vulnerability^configuration.name=contrast_url');
        gri.query();
        if (gri.next()) {
            return gri.value;
        } else {
            return '';
        }
    },
    getApiORGDetails: function() {
        var gri = new GlideRecord('sn_sec_int_impl_config');
        gri.addEncodedQuery('implementation.name=Contrast Application Vulnerability^configuration.name=org_id');
        gri.query();
        if (gri.next()) {
            return gri.value;
        } else {
            return '';
        }
    },

    //Validation script
    getApplicationListForValidation: function(implementationId) {

        var endPoint;
        endPoint = "https://" + this.getApiURLDetails() + "/Contrast/api/ng/" + this.getApiORGDetails() + "/applications";
        //Load REST API
        var r = new sn_ws.RESTMessageV2('x_ntsi_contrast_ap.Contrast REST API', 'IAST ORG');
        r.setEndpoint(endPoint);
        r.setRequestHeader('User-Agent', gs.getProperty('glide.buildtag.last'));
        r.setRequestHeader('API-Key', this.getApiKeyDetails()); //Load API-Key
        r.setRequestHeader('Authorization', this.getAuthorizationDetails()); //Load Authorization
        //r.setHttpTimeout(30000);
        var response = r.execute(); // Execute API
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();

        //Validate Response
        if (httpStatus == 200) {
            return this.getApplicationListForValidationSAST(implementationId);
        } else {
            return response;
        }
    },

    getApplicationListForValidationSAST: function(implementationId) {
        var endPoint;
        endPoint = "https://" + this.getApiURLDetails() + "/Contrast/api/sast/organizations/" + this.getApiORGDetails() + "/projects";
        //Load REST API
        var r = new sn_ws.RESTMessageV2('x_ntsi_contrast_ap.Contrast REST API', 'IAST ORG');
        r.setEndpoint(endPoint);
        r.setRequestHeader('User-Agent', gs.getProperty('glide.buildtag.last'));
        r.setRequestHeader('API-Key', this.getApiKeyDetails()); //Load API-Key
        r.setRequestHeader('Authorization', this.getAuthorizationDetails()); //Load Authorization
        return r.execute(); // Execute API
    },

    //RUN API
    triggerAPI: function(implementationId, offset, limit) {
        var endPoint;
        //Get API EndPoint val
        endPoint = "https://" + this.getApiURLDetails() + "/Contrast/api/ng/" + this.getApiORGDetails() + "/applications";

        //Load REST API
        var r = new sn_ws.RESTMessageV2('x_ntsi_contrast_ap.Contrast REST API', 'IAST ORG');
        r.setEndpoint(endPoint);
        r.setQueryParameter('offset', offset);
        r.setQueryParameter('limit', limit);
        r.setRequestHeader('User-Agent', gs.getProperty('glide.buildtag.last'));
        r.setRequestHeader('API-Key', this.getApiKeyDetails()); //Load API-Key
        r.setRequestHeader('Authorization', this.getAuthorizationDetails()); //Load Authorization
        return r.execute(); 	// Execute API, validation is there in retrieveData function
    },
    getIASTVulnerabilities: function(implementationId, appId, offset_v, limit_v) {
        var endPoint;
		endPoint = "https://" + this.getApiURLDetails() + "/Contrast/api/ng/" + this.getApiORGDetails() + "/traces/" + appId + "//filter";

        //Load REST API
        var r = new sn_ws.RESTMessageV2('x_ntsi_contrast_ap.Contrast REST API', 'IAST ORG-POST');
        r.setEndpoint(endPoint);
        r.setQueryParameter('offset', offset_v);
        r.setQueryParameter('limit', limit_v);
		r.setQueryParameter('sort', "-lastTimeSeen");
        var req = new GlideDateTime();
        var req_yesDay = new GlideDateTime();
        req_yesDay.addDaysUTC(-7);
        var dtval = new GlideDateTime(req_yesDay.getDate() + " 00:00:00");

        var objBody = {
            "startDate": dtval.getNumericValue(),
            "endDate": req.getNumericValue()
        };

        r.setRequestBody(JSON.stringify(objBody));

        r.setRequestHeader('API-Key', this.getApiKeyDetails()); //Load API-Key
        r.setRequestHeader('Authorization', this.getAuthorizationDetails()); //Load Authorization
        r.setRequestHeader('Content-Type', "application/json");
        return r.execute(); //validation is there in retrieveData function
	},

    //RUN API
    triggerAPISAST: function(implementationId,pageNumber) {
        var endPoint;
        //Load ENDPOINT
        var ScanTimeAfter = new GlideDate();
        ScanTimeAfter.addDaysUTC(-7);
        ScanTimeAfter = ScanTimeAfter + "T00:00:00Z";
        var ScanTimeBefore = new GlideDate() + "T00:00:00Z";
        endPoint = "https://" + this.getApiURLDetails() + "/Contrast/api/sast/organizations/" + this.getApiORGDetails() + "/projects?page="+pageNumber+"&lastScanTimeAfter=" + ScanTimeAfter + "&lastScanTimeBefore" + ScanTimeBefore;
        var r = new sn_ws.RESTMessageV2('x_ntsi_contrast_ap.Contrast REST API', 'IAST ORG');
        r.setEndpoint(endPoint);
        r.setRequestHeader('User-Agent', gs.getProperty('glide.buildtag.last'));
        r.setRequestHeader('API-Key', this.getApiKeyDetails()); //Load API-Key
        r.setRequestHeader('Authorization', this.getAuthorizationDetails()); //Load Authorization
        return r.execute(); 	//validation is there in retrieveData function
    },
    getSASTVulnerabilities: function(implementationId, appId, pageNumber) {
        var endPoint;
        endPoint = "https://" + this.getApiURLDetails() + "/Contrast/api/sast/organizations/" + this.getApiORGDetails() + "/projects/" + appId + "/results?page=" + pageNumber;
        var r = new sn_ws.RESTMessageV2('x_ntsi_contrast_ap.Contrast REST API', 'IAST ORG');
        r.setEndpoint(endPoint);
        r.setRequestHeader('User-Agent', gs.getProperty('glide.buildtag.last'));
        r.setRequestHeader('API-Key', this.getApiKeyDetails()); //Load API-Key
        r.setRequestHeader('Authorization', this.getAuthorizationDetails()); //Load Authorization
        return r.execute();  	//validation is there in retrieveData function
    },
    getSASTCWEID: function(implementationId, appId) {
        var endPoint;

        var r = new sn_ws.RESTMessageV2('x_ntsi_contrast_ap.Contrast REST API', 'IAST ORG');
        r.setEndpoint(appId);
        r.setRequestHeader('User-Agent', gs.getProperty('glide.buildtag.last'));
        r.setRequestHeader('API-Key', this.getApiKeyDetails()); //Load API-Key
        r.setRequestHeader('Authorization', this.getAuthorizationDetails()); //Load Authorization
        return r.execute();
    },


    type: 'ContrastUtilBase'
};
